import{_ as t,o as r,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"UGSo HA Apps","description":"","frontmatter":{},"headers":[],"relativePath":"projects-mqtt/index.md","filePath":"projects-mqtt/index.md","lastUpdated":1792778683000}'),n={name:"projects-mqtt/index.md"};function o(s,e,l,p,d,h){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="ugso-ha-apps" tabindex="-1">UGSo HA Apps <a class="header-anchor" href="#ugso-ha-apps" aria-label="Permalink to &quot;UGSo HA Apps&quot;">​</a></h1><p>Das gemeinsame Repository ist die zentrale Veröffentlichung für alle Home-Assistant-Apps von UGSo Software: MQTT-Apps, Grafik Visual Studio, Blocks for HA und zukünftige Projekte. Jede App hat ein eigenes Unterverzeichnis, eine eigene Version und Dokumentation. Die bestehende Repository-URL bleibt erhalten.</p><h2 id="ugso-ha-apps-und-weitere-projekte" tabindex="-1">UGSo HA Apps und weitere Projekte <a class="header-anchor" href="#ugso-ha-apps-und-weitere-projekte" aria-label="Permalink to &quot;UGSo HA Apps und weitere Projekte&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Projekt</th><th>Dokumentation</th></tr></thead><tbody><tr><td><a href="/projects/dashboard-user-manager/">Dashboard-Benutzerverwaltung</a></td><td>0.1.4: Benutzer als Checkbox-Spalten, Sammel-/Einzelzuordnung, automatische DE/EN/FR-Oberfläche und Dashboard-Sicherung vor dem Speichern.</td></tr><tr><td><a href="/projects/callmebot/">CallMeBot Whatsapp</a></td><td>Experimentelle HA-App 0.1.4: Empfängerprofile, WhatsApp-Texte über MQTT, DE/EN/FR und passende Blockly-Bausteine.</td></tr><tr><td><a href="/projects/callmebot-signal/">CallMeBot Signal</a></td><td>Experimentelle HA-App 0.1.0: Signal-Texte, Telefon-/UUID-Profile, eigener MQTT-Namensraum und Blockly mit Profilauswahl in DE/EN/FR.</td></tr><tr><td><a href="/projects/blocks-for-ha/">Blocks for HA</a></td><td>Experimentelle HA-App 0.1.3: visuelle Blocks für native Automationen, YAML-Import/-Export und erweiterbare Falls-Zweige; Editor über HA-Ingress.</td></tr><tr><td><a href="/projects/grafik-visual-studio/">Grafik Visual Studio</a></td><td>Grafischer Editor und Runtime für HA-Visualisierungen.</td></tr></tbody></table><p>Diese Projekte liegen im selben Repository wie die folgenden MQTT-Apps.</p><h2 id="gemeinsames-add-on-repository" tabindex="-1">Gemeinsames Add-on-Repository <a class="header-anchor" href="#gemeinsames-add-on-repository" aria-label="Permalink to &quot;Gemeinsames Add-on-Repository&quot;">​</a></h2><p>Die MQTT-Projekte werden jetzt primär über ein gemeinsames Home-Assistant-Add-on-Repository bereitgestellt. In Home Assistant muss nur eine Repository-URL eingetragen werden; danach erscheinen die einzelnen Projekte separat im Add-on Store.</p><p>Repository-URL für Home Assistant:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Enthaltene Add-ons:</p><ul><li><p>FRITZ!Box to MQTT</p></li><li><p>Heizöl to MQTT</p></li><li><p>Parcel to MQTT (Entwicklung eingestellt)</p></li><li><p><a href="/projects/mqtt-client/">MQTT-Client</a>: ausgewählte Home-Assistant-Geräte und Werte an ioBroker oder einen externen MQTT-Broker übertragen. <strong>0.1.16</strong> ergänzt Live-Zustandsänderungen mit Abfrage-Fallback, detaillierten Status, bestätigte Bereinigung eigener veralteter Retain-Topics, zusätzliche Steuerbefehle, JSON-Einstellungssicherung und eigene TLS-Zertifikate. Bestehende Einstellungen bleiben gültig; Retain-Daten werden nicht automatisch gelöscht. Der vorhandene HA-Broker bleibt bestehen.</p></li><li><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons" target="_blank" rel="noreferrer">Gemeinsames Add-on-Repository auf GitHub öffnen</a></p></li></ul><p>Die früheren Einzel-Repositories bleiben als archivierte Historie sichtbar und verweisen auf dieses gemeinsame Repository.</p><h2 id="fritz-box-to-mqtt" tabindex="-1">FRITZ!Box to MQTT <a class="header-anchor" href="#fritz-box-to-mqtt" aria-label="Permalink to &quot;FRITZ!Box to MQTT&quot;">​</a></h2><p><strong>FRITZ!Box to MQTT</strong></p><p>Eine Home-Assistant-App, die FRITZ!Box-Daten per MQTT Discovery als Entitäten bereitstellt. Sie kombiniert TR-064, FRITZ!Box-Web-/Lua-Abfragen und den Live-Anrufmonitor.</p><ul><li><a href="/projects/fritzbox-to-mqtt/">FRITZ!Box-to-MQTT-Dokumentation öffnen</a></li><li><a href="https://github.com/rockbaer2007/fritzbox-to-mqtt" target="_blank" rel="noreferrer">Archiviertes Einzel-Repository auf GitHub öffnen</a></li></ul><h2 id="heizol-to-mqtt" tabindex="-1">Heizöl to MQTT <a class="header-anchor" href="#heizol-to-mqtt" aria-label="Permalink to &quot;Heizöl to MQTT&quot;">​</a></h2><p><strong>Heizöl to MQTT</strong></p><p>Eine Home-Assistant-App, die Heizölpreise von Esyoil und Heizöl24 per MQTT Discovery als Entitäten bereitstellt. Aktuell werden Bestpreise und bis zu sechs Anbieter-Angebote pro Quelle und Menge veröffentlicht.</p><ul><li><a href="/projects/heizoel-to-mqtt/">Heizöl-to-MQTT-Dokumentation öffnen</a></li><li><a href="https://github.com/rockbaer2007/heizoel-to-mqtt" target="_blank" rel="noreferrer">Archiviertes Einzel-Repository auf GitHub öffnen</a></li><li>Adaptiert von: <a href="https://github.com/TA2k/ioBroker.heizoel" target="_blank" rel="noreferrer">TA2k/ioBroker.heizoel</a></li></ul><h2 id="parcel-to-mqtt" tabindex="-1">Parcel to MQTT <a class="header-anchor" href="#parcel-to-mqtt" aria-label="Permalink to &quot;Parcel to MQTT&quot;">​</a></h2><p><strong>Parcel to MQTT</strong></p><p><strong>Entwicklung eingestellt:</strong> Parcel Tracker ist bereits deutlich weiter entwickelt. Deshalb stellen wir die Weiterentwicklung unseres Pakets ein. Wir empfehlen einen Blick auf <a href="https://github.com/SoerenKaiser99/parcel_tracker" target="_blank" rel="noreferrer">Parcel Tracker von SoerenKaiser99</a>. Unsere bisherige Dokumentation bleibt als Archiv erhalten.</p><p>Eine Home-Assistant-App, die Paketverfolgung per MQTT Discovery als Entitäten bereitstellt. Die aktuelle Version nutzt DHL-Konto-Paketlisten, optionale DHL-Sendungsnummern und Hermes-Paketverfolgung.</p><ul><li><a href="/projects/parcel-to-mqtt/">Parcel-to-MQTT-Dokumentation öffnen</a></li><li><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/parcel_to_mqtt" target="_blank" rel="noreferrer">Paket im gemeinsamen Add-on-Repository öffnen</a></li><li><a href="https://github.com/rockbaer2007/parcel-to-mqtt" target="_blank" rel="noreferrer">Archiviertes Einzel-Repository auf GitHub öffnen</a></li><li>Adaptiert von: <a href="https://github.com/TA2k/ioBroker.parcel" target="_blank" rel="noreferrer">TA2k/ioBroker.parcel</a></li></ul><h2 id="weitere-projektbereiche" tabindex="-1">Weitere Projektbereiche <a class="header-anchor" href="#weitere-projektbereiche" aria-label="Permalink to &quot;Weitere Projektbereiche&quot;">​</a></h2><ul><li><a href="/projects/">C# Projekte öffnen</a></li><li><a href="/projects-diverse/">Diverse Projekte öffnen</a></li><li><a href="/projects/atlas/">ATLAS öffnen</a></li></ul>',27)])])}const m=t(n,[["render",o]]);export{c as __pageData,m as default};
